mapper.select:
SELECT u.id, u.tenant_id, u.username, u.nickname, u.real_name, u.gender, u.avatar, u.phone, u.email, u.user_type, u.is_superadmin, u.status, u.status_time, u.status_reason, u.login_fail_count, u.must_change_password, u.password_update_time, u.effective_start_time, u.effective_end_time, u.last_login_ip, u.last_login_time, u.is_builtin, u.source_type, u.remark, u.version, u.create_time, u.update_time, u.create_by, u.update_by, d.name AS dept_name, r.role_names FROM sys_user u
LEFT JOIN sys_user_dept ud ON ud.user_id = u.id AND ud.is_deleted = 0 AND ud.is_primary = 1 LEFT JOIN sys_dept d ON d.id = ud.dept_id AND d.is_deleted = 0
LEFT JOIN ( SELECT ur.user_id, GROUP_CONCAT(r.name ORDER BY r.sort SEPARATOR ', ') AS role_names FROM sys_user_role ur INNER JOIN sys_role r ON r.id = ur.role_id AND r.is_deleted = 0 WHERE ur.is_deleted = 0 GROUP BY ur.user_id ) r ON r.user_id = u.id WHERE u.is_deleted = 0 AND u.tenant_id = #{tenantId} AND u.user_type = 'backend'
AND u.user_type = #{req.userType}
AND ud.dept_id = #{req.deptId}
AND (u.username LIKE CONCAT('%', #{req.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{req.keyword}, '%') OR u.real_name LIKE CONCAT('%', #{req.keyword}, '%') OR u.phone LIKE CONCAT('%', #{req.keyword}, '%') OR u.email LIKE CONCAT('%', #{req.keyword}, '%'))
AND u.username LIKE CONCAT('%', #{req.username}, '%')
AND u.nickname LIKE CONCAT('%', #{req.nickname}, '%')
AND u.status = #{req.status}
GROUP BY u.id, d.name
ORDER BY d.name ${req.safeOrderDirection()}
ORDER BY u.${req.safeOrderBy()} ${req.safeOrderDirection()}
ORDER BY u.create_time DESC
